from django.db import migrations, models


def cargar_desde_pacientes(apps, schema_editor):
    """Parte con los diagnósticos que ya tienen los pacientes (uno por línea)."""
    Paciente = apps.get_model("pacientes", "Paciente")
    Diagnostico = apps.get_model("pacientes", "Diagnostico")
    nombres = set()
    for texto in Paciente.objects.exclude(diagnostico="").values_list("diagnostico", flat=True).distinct():
        for linea in str(texto).splitlines():
            nombre = " ".join(linea.split()).upper()
            if nombre and len(nombre) <= 255:
                nombres.add(nombre)
    Diagnostico.objects.bulk_create([Diagnostico(nombre=n) for n in sorted(nombres)], ignore_conflicts=True)


